// Bling API v3 - link de autorização e leitura do callback (Node 18+)
import { randomBytes } from "node:crypto";

const CLIENT_ID = process.env.BLING_CLIENT_ID ?? "<<SEU_CLIENT_ID>>";

export function linkAutorizacao(): { url: string; state: string } {
  const state = randomBytes(24).toString("hex"); // guarde na sessão
  const qs = new URLSearchParams({ response_type: "code", client_id: CLIENT_ID, state });
  return { url: `https://www.bling.com.br/Api/v3/oauth/authorize?${qs}`, state };
}

export function lerCallback(urlCallback: string, stateEsperado: string): string {
  const q = new URL(urlCallback).searchParams;
  if (q.get("error")) throw new Error(`Autorização negada: ${q.get("error")} ${q.get("error_description") ?? ""}`);
  if (q.get("state") !== stateEsperado) throw new Error("state divergente (CSRF)");
  const code = q.get("code");
  if (!code) throw new Error("callback sem code");
  return code; // troque em até 1 minuto
}

const { url } = linkAutorizacao();
console.log("Abra no navegador:", url);

// Bling API v3 - troca de code e renovação (Node 18+)
import { readFile, writeFile } from "node:fs/promises";

const TOKEN_URL = "https://api.bling.com.br/Api/v3/oauth/token";
const CLIENT_ID = process.env.BLING_CLIENT_ID ?? "<<SEU_CLIENT_ID>>";
const CLIENT_SECRET = process.env.BLING_CLIENT_SECRET ?? "<<SEU_CLIENT_SECRET>>";
const ARQUIVO = "bling_tokens.json"; // em produção: banco ou cofre

async function postToken(dados: Record<string, string>) {
  const basic = Buffer.from(`${CLIENT_ID}:${CLIENT_SECRET}`).toString("base64");
  const r = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { Authorization: `Basic ${basic}`, Accept: "1.0", "enable-jwt": "1",
               "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(dados),
  });
  const corpo = await r.json();
  if (!r.ok) throw new Error(`OAuth Bling ${r.status}: ${corpo?.error?.type} ${corpo?.error?.description}`);
  corpo.expira_em = Date.now() + (corpo.expires_in - 60) * 1000;
  await writeFile(ARQUIVO, JSON.stringify(corpo));
  return corpo;
}

export const trocarCode = (code: string) => postToken({ grant_type: "authorization_code", code });

export async function tokenValido(): Promise<string> {
  const t = JSON.parse(await readFile(ARQUIVO, "utf8"));
  if (Date.now() < t.expira_em) return t.access_token;
  return (await postToken({ grant_type: "refresh_token", refresh_token: t.refresh_token })).access_token;
}

