"""Bling API v3 - revogação de tokens. Requer: pip install requests"""
import requests

CLIENT_ID = "<<SEU_CLIENT_ID>>"
CLIENT_SECRET = "<<SEU_CLIENT_SECRET>>"


def revogar(token, tipo="refresh_token", acao=None, alvo=None):
    dados = {"token": token, "token_type_hint": tipo}
    if acao:
        dados["revoke_action"] = acao      # logout | uninstall
    if alvo:
        dados["revoke_target"] = alvo      # user | company
    r = requests.post("https://api.bling.com.br/oauth/revoke", data=dados,
                      auth=(CLIENT_ID, CLIENT_SECRET), timeout=30)
    if r.status_code >= 400:
        raise RuntimeError(f"Revogação falhou: {r.status_code} {r.text}")
    return True


if __name__ == "__main__":
    revogar("<<SEU_REFRESH_TOKEN>>", acao="logout")

