// Bling API v3 - Obtém um pedido de compra (Power Query M: Excel / Power BI)
// AccessToken e o ID como parâmetros do Power Query (Gerenciar Parâmetros), não texto fixo.
let
    BaseUrl = "https://api.bling.com.br",
    AccessToken = "<<SEU_ACCESS_TOKEN>>",
    Resposta = Web.Contents(BaseUrl, [
                RelativePath = "Api/v3/pedidos/compras/12345678",
                Headers = [Authorization = "Bearer " & AccessToken, Accept = "application/json", #"enable-jwt" = "1"],
                ManualStatusHandling = {400, 401, 403, 404, 429, 500}
            ]),
    Status = Record.FieldOrDefault(Value.Metadata(Resposta), "Response.Status", null),
    Corpo = Json.Document(Resposta),
    Dados = if Status = null then error "Credencial recusada pelo Bling (HTTP 401/403): renove o AccessToken"
        else if Status = 200 then Corpo[data]
            else error Error.Record("Bling HTTP " & Text.From(Status),
                 try Corpo[error][type] & ": " & Corpo[error][description] otherwise "sem detalhe"),
    // registro único -> tabela de duas colunas (campo/valor); objetos aninhados ficam como Record
    Tabela = if Value.Is(Dados, type list)
             then Table.FromRecords(Dados, null, MissingField.UseNull)
             else Record.ToTable(Dados)
in
    Tabela

