    "vencimento": "2026-10-05",
    "valor": 890.0,
    "contato": {
        "id": 87654321
    },
    "formaPagamento": {
        "id": 1122
    },
    "dataEmissao": "2026-09-17",
    "numeroDocumento": "NF-4455",
    "historico": "Compra de insumos",
    "categoria": {
        "id": 3345
    }
}


def conta_pagar_criar():
    return bling("POST", "/contas/pagar", json=CORPO)


if __name__ == "__main__":
    print(conta_pagar_criar())

