// Bling API v3 - Cria uma remessa de postagem de uma logística (Node 18+ / fetch nativo)
// Credenciais vêm do fluxo OAuth2 (authorization code). Persista o refresh_token.
const BASE_URL = "https://api.bling.com.br/Api/v3";
const CLIENT_ID = process.env.BLING_CLIENT_ID ?? "<<SEU_CLIENT_ID>>";
const CLIENT_SECRET = process.env.BLING_CLIENT_SECRET ?? "<<SEU_CLIENT_SECRET>>";
const tokens = { access_token: "<<SEU_ACCESS_TOKEN>>", refresh_token: "<<SEU_REFRESH_TOKEN>>" };
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function renovarToken(): Promise<void> {
  const basic = Buffer.from(`${CLIENT_ID}:${CLIENT_SECRET}`).toString("base64");
  const r = await fetch(`${BASE_URL}/oauth/token`, {
    method: "POST",
    headers: { Authorization: `Basic ${basic}`, Accept: "1.0", "enable-jwt": "1",
               "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "refresh_token", refresh_token: tokens.refresh_token }),
  });
  if (!r.ok) throw new Error(`Falha ao renovar token: ${r.status} ${await r.text()}`);
  Object.assign(tokens, await r.json()); // persista o novo par de tokens
}

async function bling(metodo: string, caminho: string, corpo?: unknown): Promise<any> {
  let renovado = false;
  for (let tentativa = 0; tentativa < 5; tentativa++) {
    const r = await fetch(BASE_URL + caminho, {
      method: metodo,
      headers: { Authorization: `Bearer ${tokens.access_token}`, Accept: "application/json",
                 "Content-Type": "application/json", "enable-jwt": "1" },
      body: corpo === undefined ? undefined : JSON.stringify(corpo),
    });
    if (r.status === 401 && !renovado) { await renovarToken(); renovado = true; continue; }
    if (r.status === 429) { await sleep(2 ** tentativa * 1000); continue; }
    const texto = await r.text();
    if (!r.ok) throw new Error(`Bling HTTP ${r.status}: ${texto}`);
    return texto ? JSON.parse(texto) : null;
  }
  throw new Error("Bling: 429 persistente");
}

const corpo = {
  "numeroPlp": "PLP-20260917",
  "situacao": 0,
  "descricao": "Remessa_17092026",
  "logistica": {
    "id": 5566
  },
  "objetos": [
    {
      "id": 12345678
    }
  ]
};

export async function envioCriarRemessa(): Promise<any> {
  return bling("POST", "/logisticas/remessas", corpo);
}

envioCriarRemessa().then((r) => console.log(JSON.stringify(r, null, 2))).catch(console.error);
